  "prediction_basis_card_ids": ["C49", "C58", "C55"],
  "claims": [
    {
      "claim": "Decitabine is a polar 5-aza-2'-deoxycytidine nucleoside with low predicted passive permeability; L4 shows the close deoxycytidine analog gemcitabine has low Caco-2 permeability (Papp 0.99×10^-6 and <1×10^-6 cm/s), and the polar nucleoside GS-441524 has low PAMPA permeability (<1×10^-6 cm/s), providing affirmative measured absorption evidence against high oral absorption for this class.",
      "card_ids": ["C49", "C58", "C55"]
    },
    {
      "claim": "High solubility records for ribavirin and the absorptive jejunal flux of lamivudine show that some polar nucleosides can be absorbed, but they do not establish decitabine-specific absorption; lamivudine is a dideoxy nucleoside with a different transporter/efflux profile, and no decitabine transport data are supplied.",
      "card_ids": ["C47", "C50", "C57", "C48", "C52"]
    },
    {
      "claim": "Direct high absolute bioavailability values for zalcitabine, lamivudine, doxifluridine, and other nucleosides are less transferable to decitabine because of different sugar/nucleobase modifications and do not outweigh the measured low permeability of closer deoxycytidine analogs.",
      "card_ids": ["C19", "C31", "C06", "C07", "C17", "C22", "C29", "C30", "C03", "C08", "C09", "C12", "C23", "C24", "C01", "C21", "C04", "C13", "C14", "C18", "C25", "C32"]
    },
    {
      "claim": "No direct decitabine absolute oral bioavailability measurement or evidence of active transport/first-pass protection is present; the unfavorable absorption prior and low permeability evidence support F < 20%.",
      "card_ids": ["C49", "C58", "C55"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C49", "C58", "C55", "C47", "C50", "C57", "C48", "C52"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for decitabine is present in the supplied records.",
    "No decitabine-specific Caco-2/PAMPA, solubility, or transporter data are available; gemcitabine and GS-441524 are structural proxies.",
    "No data on acid stability of the 5-aza-triazinone ring or cytidine deaminase-mediated first-pass metabolism are supplied.",
    "No gut-wall efflux or intestinal metabolism data for decitabine are available at this level.",
    "Active nucleoside transport could compensate for low passive permeability, but no card provides evidence for such transport in decitabine."
  ],
  "decision_summary": "Predicted low (F < 20%) because L4 provides affirmative measured low permeability for close deoxycytidine/nucleoside analogs (gemcitabine Caco-2 Papp <1×10^-6 cm/s; GS-441524 PAMPA <1×10^-6 cm/s), consistent with the unfavorable passive permeability prior for this polar 5-aza-2'-deoxycytidine; high F values for dideoxycytidine analogs are less transferable, and no decitabine-specific absorption or active-transport evidence is supplied. Confidence is low because the decisive permeability data are indirect."
}

